        authorize_calendar_action,
    },
    caldav::{
        MAX_LABEL_LENGTH,
        auth::CaldavAccountService,
        ical::{CaldavIcalEvent, etag_for_ical, serialize_event_resource},
        query::{self, CalendarMultiget, CalendarQuery, MAX_RESULTS},
        repository::CaldavRepository,
        types::{
            CaldavAuthError, CaldavCalendar, CaldavEventResource, CredentialMetadata, DavSession,
            PrincipalInfo,
        },
    },
    event::{
        Event, EventChange, EventMutation, EventRepository, EventService, EventServiceError,
        EventStatus, EventTiming,
    },
