        .create(user_id, false, calendar_id, timed_mutation())
        .await
        .unwrap();

    assert_eq!(
        change_count(&pool, calendar_id, Some("created")).await,
        1,
        "a committed native create must record exactly one 'created' change"
    );
    assert_eq!(
        change_count(&pool, calendar_id, None).await,
